package com.aistock.prediction.comparison;
import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.prediction.comparison.ComparisonTestEvidence.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;
class ComparisonCalculatorTest {
 Input input(List<JsonNode> e){return new Input(UUID.randomUUID(),e.stream().map(n->n.path("instrumentId").asText()).toList(),LocalDate.parse("2026-07-09"),LocalDate.parse("2026-10-09"),e.stream().map(n->UUID.fromString(n.path("evidenceId").asText())).toList());}
 Calculation calc(JsonNode a,JsonNode b){var e=List.of(a,b);return new ComparisonCalculator().calculate(input(e),e);}
 @Test void independentlyReproducibleFormulas(){var r=calc(sample("SH600030",new String[]{"100","110","99"},new String[]{"10","20","30"}),sample("SH600276",new String[]{"10","11","9.9"},new String[]{"10","20","30"}));var s=r.stocks().get(0);assertEquals("-1.000000",s.intervalReturn().value());assertEquals("10.000000",s.maxDrawdown().value());assertEquals("20.0000",s.meanVolume().value());assertEquals("224.499443",s.annualizedVolatility().value());assertEquals(s.intervalReturn(),r.stocks().get(1).intervalReturn());assertEquals(2,s.annualizedVolatility().observationCount());assertEquals("100.000000",s.chart().get(0).normalizedClose());}
 @Test void missingVolumeOnlyAffectsVolumeAndMissingPriceOnlyOwnRisks(){var a=sample("SH600030",new String[]{"100",null,"99"},new String[]{"10","20","30"});var b=sample("SH600276",new String[]{"10","11","12"},new String[]{"10",null,"30"});var r=calc(a,b);assertEquals("AVAILABLE",r.stocks().get(0).intervalReturn().status());assertEquals("UNAVAILABLE",r.stocks().get(0).maxDrawdown().status());assertNull(r.stocks().get(0).chart().get(1).normalizedClose());assertEquals("20.0000",r.stocks().get(0).meanVolume().value());assertEquals("AVAILABLE",r.stocks().get(1).maxDrawdown().status());assertEquals("UNAVAILABLE",r.stocks().get(1).meanVolume().status());}
 @Test void noTwoEndpointsDoesNotInventZero(){var a=sample("SH600030",new String[]{null,"100",null},new String[]{"10","20","30"});var b=sample("SH600276",new String[]{"10","10","10"},new String[]{"10","20","30"});var r=calc(a,b);assertNull(r.actualRange());assertNull(r.stocks().get(0).intervalReturn().value());}
 @Test void zeroVarianceRisingFallingAndOrderInvariant(){for(String[] prices:new String[][]{{"10","10","10"},{"10","20","40"},{"40","20","10"},{"20","10","30"}}){var a=sample("SH600030",prices,new String[]{"0","20","30"});var b=sample("SH600276",prices,new String[]{"0","20","30"});var forward=calc(a,b);var reverse=calc(b,a);assertEquals(forward.stocks().get(0),reverse.stocks().get(1));if(prices[0].equals("10"))assertEquals("0.000000",forward.stocks().get(0).annualizedVolatility().value());}}
 @Test void twoPricesAllowDrawdownButNotVolatility(){var a=sample("SH600030",new String[]{null,"100","90"},new String[]{"10","20","30"});var b=sample("SH600276",new String[]{"10","10","10"},new String[]{"10","20","30"});var r=calc(a,b).stocks().get(0);assertEquals("10.000000",r.maxDrawdown().value());assertEquals("UNAVAILABLE",r.annualizedVolatility().status());}
 @Test void invalidHashMappingAndCalendarAreRejected(){var a=sample("SH600030",new String[]{"10","10","10"},new String[]{"10","20","30"});var b=sample("SH600276",new String[]{"10","10","10"},new String[]{"10","20","30"});a.put("contentHash","f".repeat(64));assertThrows(RuntimeException.class,()->calc(a,b));rehash(a);b.withArray("calendar").get(0).deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)b.withArray("calendar").get(0)).put("open",true);rehash(b);assertThrows(RuntimeException.class,()->calc(a,b));}
 @Test void missingVolumeAndSuspensionRemainDistinctInSavedResult(){var a=sample("SH600030",new String[]{"10","11","12"},new String[]{"10",null,"30"});var b=sample("SH600276",new String[]{"10",null,"12"},new String[]{"10",null,"30"});var suspended=(com.fasterxml.jackson.databind.node.ObjectNode)b.withArray("days").get(1);suspended.put("priceState","SUSPENDED").put("volumeState","SUSPENDED");rehash(b);var r=calc(a,b);var data=M.copy().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).valueToTree(r);assertEquals("MISSING",data.path("stocks").get(0).path("dataIssues").get(0).path("state").asText());assertEquals("volumeShares",data.path("stocks").get(0).path("dataIssues").get(0).path("field").asText());assertEquals("2026-10-08",data.path("stocks").get(1).path("dataIssues").get(0).path("date").asText());assertEquals("SUSPENDED",data.path("stocks").get(1).path("dataIssues").get(0).path("state").asText());assertEquals("AVAILABLE",r.stocks().get(0).maxDrawdown().status());assertNull(r.stocks().get(1).chart().get(1).normalizedClose());}
}
